//! The Rust of Hostkit.Clock, ported from C# (CodeCoreMorph, D-84).
use std::sync::OnceLock;
use std::time::Instant;

/// A monotonic clock in nanoseconds, from the operating system's own.
pub struct Clock;

/// The fixed point the clock counts from: its first reading.
fn origin() -> Instant {
    static ORIGIN: OnceLock<Instant> = OnceLock::new();
    *ORIGIN.get_or_init(Instant::now)
}

impl Clock {
    /// Nanoseconds since some fixed point; never goes back.
    pub fn nanoseconds() -> i64 {
        // What the C# does on Linux, clock_gettime(CLOCK_MONOTONIC), is std's Instant there;
        // its branch for Windows (QueryPerformanceCounter) isn't this port's, which is built for
        // Linux (D-94). std keeps the clock's reading to itself, so the fixed point is the
        // first call's.
        i64::try_from(origin().elapsed().as_nanos()).unwrap_or(i64::MAX)
    }

    /// Milliseconds from `start` (a `nanoseconds` value) to now.
    pub fn milliseconds_since(start: i64) -> f64 {
        Self::nanoseconds().wrapping_sub(start) as f64 / 1_000_000.0
    }
}

