//! The Rust of Hostkit.Host, ported from C# (CodeCoreMorph, D-84).
//!
//! What the C# does on Linux: getpid and strerror from the C library, which std calls too. Its
//! branches for Windows (GetCurrentProcessId, FormatMessageW) aren't this port's, which is built
//! for Linux (D-94).

/// What the process can ask its operating system.
pub struct Host;

impl Host {
    /// The process's ID.
    pub fn process_id() -> i32 {
        // getpid's pid_t, which std hands back as a u32.
        std::process::id() as i32
    }

    /// The system's message for an error code (an errno), without a trailing newline or period.
    pub fn error_message(code: i32) -> String {
        // strerror's text, which std reads with strerror_r, without the " (os error N)" std adds.
        let full = std::io::Error::from_raw_os_error(code).to_string();
        let suffix = format!(" (os error {code})");
        let text = full.strip_suffix(&suffix).unwrap_or(&full);
        // C#'s TrimEnd('\r', '\n', ' ', '.').
        text.trim_end_matches(['\r', '\n', ' ', '.']).to_owned()
    }
}

