//! The Rust of Hostkit.Terminal, ported from C# (CodeCoreMorph, D-84).

/// ANSI colors on a terminal.
pub struct Terminal;

impl Terminal {
    /// Lets the console show ANSI colors: a terminal on Linux shows them as they are, so there is
    /// nothing to ask.
    pub fn enable_colors() -> bool {
        // What the C# does on Linux. Its branch for Windows asks the console for virtual
        // terminal processing (GetStdHandle, GetConsoleMode, SetConsoleMode), which isn't this
        // port's, built for Linux (D-94).
        true
    }

    /// `text` in one of the eight ANSI colors (0 to 7).
    pub fn paint(text: &str, color: i32) -> String {
        format!("\x1b[3{}m{text}\x1b[0m", color & 7)
    }
}

