//! The tests of tests/Hostkit.Tests/HostkitTests.cs, translated from C# (CodeCoreMorph, D-84): a
//! Rust test per C# test case, each mapped in rust/test-map.toml.
use std::thread;
use std::time::Duration;

use hostkit_rs::clock::Clock;
use hostkit_rs::host::Host;
use hostkit_rs::terminal::Terminal;

// ClockTests

#[test]
fn never_goes_back() {
    let a = Clock::nanoseconds();
    let b = Clock::nanoseconds();
    assert!(b >= a);
}

#[test]
fn measures_a_sleep() {
    let start = Clock::nanoseconds();
    thread::sleep(Duration::from_millis(30));
    assert!((25.0..=2000.0).contains(&Clock::milliseconds_since(start)));
}

// HostTests

#[test]
fn the_process_id() {
    assert_eq!(std::process::id() as i32, Host::process_id());
}

#[test]
fn an_error_message() {
    // ENOENT is 2. The C# expects Windows' text on Windows; the port runs on Linux (D-94).
    assert_eq!("No such file or directory", Host::error_message(2));
}

// TerminalTests

#[test]
fn paints_in_ansi_colors() {
    assert_eq!("\x1b[32mok\x1b[0m", Terminal::paint("ok", 2));
    assert_eq!("\x1b[31mx\x1b[0m", Terminal::paint("x", 9));
}

#[test]
fn enabling_colors_does_not_throw() {
    assert!(std::panic::catch_unwind(Terminal::enable_colors).is_ok());
}
